package com.xiaomiscalesync.crypto

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test

/**
 * Known-answer tests for [AesCcm] against fixtures generated by
 * `scripts/gen_vectors.py` (Python `cryptography` AESCCM, tag length 4).
 */
class AesCcmTest {

    private val fixtures: List<VectorFixture.Ccm> =
        Vectors.load("crypto_vectors").filterIsInstance<VectorFixture.Ccm>()

    @Test
    fun loadsAllCcmFixtures() {
        assertEquals(listOf("ccm_no_aad", "ccm_aad", "session_enc"), fixtures.map { it.name })
    }

    @Test
    fun encryptMatchesPinnedCiphertext() {
        for (f in fixtures) {
            val out = AesCcm.encrypt(f.key, f.nonce, f.aad, f.plaintext)
            assertArrayEquals("encrypt(${f.name})", f.ciphertext, out)
        }
    }

    @Test
    fun decryptRecoversPinnedPlaintext() {
        for (f in fixtures) {
            val out = AesCcm.decrypt(f.key, f.nonce, f.aad, f.ciphertext)
            assertArrayEquals("decrypt(${f.name})", f.plaintext, out)
        }
    }

    @Test
    fun outputIsPlaintextLengthPlusFourByteTag() {
        for (f in fixtures) {
            val out = AesCcm.encrypt(f.key, f.nonce, f.aad, f.plaintext)
            assertEquals("encrypt(${f.name})", f.plaintext.size + 4, out.size)
        }
    }

    @Test
    fun wrongKeyThrowsAuthenticationMismatch() {
        val f = fixtures.first()
        val wrongKey = f.key.copyOf().also { it[0] = (it[0].toInt() xor 0x01).toByte() }
        assertThrows(AuthenticationMismatch::class.java) {
            AesCcm.decrypt(wrongKey, f.nonce, f.aad, f.ciphertext)
        }
    }

    @Test
    fun flippedTagByteThrowsAuthenticationMismatch() {
        for (f in fixtures) {
            val tampered = f.ciphertext.copyOf()
            val last = tampered.lastIndex
            tampered[last] = (tampered[last].toInt() xor 0x01).toByte()
            assertThrows("decrypt(${f.name})", AuthenticationMismatch::class.java) {
                AesCcm.decrypt(f.key, f.nonce, f.aad, tampered)
            }
        }
    }

    @Test
    fun flippedCiphertextByteThrowsAuthenticationMismatch() {
        val f = fixtures.first()
        val tampered = f.ciphertext.copyOf()
        tampered[0] = (tampered[0].toInt() xor 0x01).toByte()
        assertThrows(AuthenticationMismatch::class.java) {
            AesCcm.decrypt(f.key, f.nonce, f.aad, tampered)
        }
    }

    @Test
    fun wrongAadThrowsAuthenticationMismatch() {
        val f = fixtures.first { it.aad != null }
        val wrongAad = f.aad!!.copyOf().also { it[0] = (it[0].toInt() xor 0x01).toByte() }
        assertThrows(AuthenticationMismatch::class.java) {
            AesCcm.decrypt(f.key, f.nonce, wrongAad, f.ciphertext)
        }
    }

    @Test
    fun dataShorterThanTagThrowsAuthenticationMismatch() {
        val f = fixtures.first()
        assertThrows(AuthenticationMismatch::class.java) {
            AesCcm.decrypt(f.key, f.nonce, f.aad, ByteArray(3))
        }
    }

    @Test
    fun sevenByteNonceRoundTrips() {
        // RFC 3610 allows nonces down to 7 bytes (L = 8); guards the Q-field
        // length check against Long-shift wraparound.
        val f = fixtures.first()
        val nonce = f.nonce.copyOf(7)
        val out = AesCcm.encrypt(f.key, nonce, null, f.plaintext)
        assertArrayEquals(f.plaintext, AesCcm.decrypt(f.key, nonce, null, out))
    }
}
